begin;
create function pg_temp.care_assert(ok boolean,label text) returns text language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;return label;end $$;
create function pg_temp.care_denied(stmt text,label text,expected text default '42501') returns text language plpgsql as $$begin begin execute stmt;exception when others then if sqlstate<>expected then raise exception 'Wrong error % for %',sqlstate,label;end if;return label;end;raise exception 'Unexpected success: %',label;end $$;
create function pg_temp.record_p(n integer,kind text,v integer default 0) returns jsonb language sql as $$select jsonb_build_object('id',('b4000000-0000-4000-8000-'||lpad(n::text,12,'0')),'patient_id','b2000000-0000-4000-8000-000000000001','event_id',('b3000000-0000-4000-8000-'||lpad(n::text,12,'0')),'specialty',kind,'version',v,'operation_key',gen_random_uuid(),'occurred_at',now()-interval '2 hours','payload',jsonb_build_object('objective','Objetivo neutro QA','evolution','not_evaluable','facts','Hechos neutros QA'),'reserved_note','','summary_body','','summary_visibility','none','request_intervention',false,'request_body','','request_due_at','','reason','','confirm_finalize',true,'confirm_publish',false)$$;
create temporary table records_fixture(name text primary key,p jsonb);
grant select,insert,update on records_fixture to authenticated;
insert into auth.users(id,email) select ('b1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'records-fixture-'||n||'@example.test' from generate_series(1,7)n;
insert into public.admin_users(user_id,role,is_active) select ('b1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,(case when n=7 then 'editor' else 'viewer' end)::public.admin_role,true from generate_series(3,7)n;
insert into public.patient_profiles(id,auth_user_id,email,display_name) select ('b2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('b1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'records-fixture-'||n||'@example.test','Persona record QA '||n from generate_series(1,2)n;
insert into public.care_staff_capabilities(user_id,capabilities) select ('b1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,array['care.directory.read','care.patient.read','care.records.read','care.records.create']||case when n=5 then array['care.medical.create'] else array[]::text[] end from generate_series(3,5)n;
insert into public.care_staff_capabilities(user_id,capabilities) values('b1000000-0000-4000-8000-000000000006',array['care.directory.read','care.patient.read','care.records.read','care.assignments.manage','care.decisions.manage']);
insert into public.care_assignments(patient_id,professional_id,specialty,starts_at,created_by) select 'b2000000-0000-4000-8000-000000000001',('b1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case n when 3 then 'psychology' when 4 then 'recovery' when 5 then 'psychiatry' else 'direction' end,now()-interval '1 day','b1000000-0000-4000-8000-000000000006' from generate_series(3,6)n;
insert into public.care_assignments(patient_id,professional_id,specialty,starts_at,created_by) values('b2000000-0000-4000-8000-000000000002','b1000000-0000-4000-8000-000000000006','direction',now()-interval '1 day','b1000000-0000-4000-8000-000000000006');
insert into public.care_events(id,title,kind,starts_at,ends_at,professional_id,modality,status,closed_at,created_by) select ('b3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Sesión neutra QA '||n,case n when 2 then 'recovery' when 3 then 'psychiatry' else 'individual' end,now()-interval '2 hours',now()-interval '1 hour',('b1000000-0000-4000-8000-'||lpad((case n when 2 then 4 when 3 then 5 when 4 then 6 else 3 end)::text,12,'0'))::uuid,'in_person',case when n=5 then 'cancelled' else 'completed' end,now()-interval '30 minutes',('b1000000-0000-4000-8000-'||lpad((case n when 2 then 4 when 3 then 5 when 4 then 6 else 3 end)::text,12,'0'))::uuid from generate_series(1,6)n;
insert into public.care_event_participants(event_id,patient_id,attendance) select id,'b2000000-0000-4000-8000-000000000001',case when title like '%6' then 'pending' else 'present' end from public.care_events where id::text like 'b3000000-%';
set local role anon;
select pg_temp.care_denied($$select * from public.care_session_records$$,'Anon no records');
select pg_temp.care_denied($$select public.care_record_read('b4000000-0000-4000-8000-000000000001')$$,'Anon no record RPC');
reset role;set local role authenticated;select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000003',true);
insert into records_fixture values('draft',pg_temp.record_p(1,'psychology')||jsonb_build_object('payload',jsonb_build_object('objective','','evolution','','facts','Borrador clínico privado QA'),'reserved_note','Reserva privada QA'));
select public.care_record_write('draft',(select p from records_fixture where name='draft'));
select pg_temp.care_assert((select count(*)=1 from public.care_session_records),'Own draft metadata available');
select pg_temp.care_assert(public.care_record_read('b4000000-0000-4000-8000-000000000001')->'draft'->'payload'->>'facts'='Borrador clínico privado QA','Incomplete draft persists only for author');
select pg_temp.care_assert(jsonb_array_length(public.care_record_read('b4000000-0000-4000-8000-000000000001')->'versions')=0,'Draft is not finalized revision');
select public.care_record_write('draft',(select p from records_fixture where name='draft'));
select pg_temp.care_assert((select version=1 from public.care_session_records),'Operation key replay does not duplicate draft version');
select pg_temp.care_denied($$select public.care_record_write('draft',pg_temp.record_p(1,'psychology'))$$,'Stale draft rejected','40001');
select pg_temp.care_denied($$select public.care_record_write('draft',(select p||'{"reserved_note":"Changed"}'::jsonb from records_fixture where name='draft'))$$,'Same operation key different content rejected','P0001');
select pg_temp.care_denied($$select * from private.care_record_drafts$$,'No direct draft table grant');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000006',true);
select pg_temp.care_assert((select count(*)=0 from public.care_session_records),'Direction does not see author draft metadata');
select pg_temp.care_denied($$select public.care_record_read('b4000000-0000-4000-8000-000000000001')$$,'Direction cannot read draft body');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000003',true);
select pg_temp.care_denied($$select public.care_record_write('finalize',pg_temp.record_p(1,'psychology',1)||'{"confirm_finalize":false}'::jsonb)$$,'Finalization requires explicit confirmation','P0001');
select pg_temp.care_denied($$select public.care_record_write('finalize',pg_temp.record_p(1,'psychology',1)||jsonb_build_object('payload',jsonb_build_object('objective','QA objetivo','evolution','')))$$,'Evolution has no default at finalization','P0001');
select pg_temp.care_denied($$select public.care_record_write('finalize',pg_temp.record_p(1,'psychology',1)||jsonb_build_object('payload',jsonb_build_object('objective','QA objetivo','evolution','not_evaluable','medical_indications','Forjada')))$$,'Psychology cannot inject medical field','P0001');
select pg_temp.care_denied($$select public.care_record_write('finalize',pg_temp.record_p(4,'psychology'))$$,'Assigned professional cannot impersonate event owner');
select pg_temp.care_denied($$select public.care_record_write('finalize',pg_temp.record_p(5,'psychology'))$$,'Cancelled session cannot be recorded');
select pg_temp.care_denied($$select public.care_record_write('finalize',pg_temp.record_p(6,'psychology'))$$,'Attendance pending blocks finalization','P0001');
select pg_temp.care_denied($$select public.care_record_write('finalize',pg_temp.record_p(1,'psychology',1)||jsonb_build_object('occurred_at',now()+interval '1 day'))$$,'Future clinical fact cannot finalize','P0001');
select pg_temp.care_denied($$select public.care_record_write('finalize',pg_temp.record_p(1,'psychology',1)||'{"summary_visibility":"patient","summary_body":"Compartido QA"}'::jsonb)$$,'Summary publication needs explicit confirmation','P0001');
insert into records_fixture values('original',pg_temp.record_p(1,'psychology',1)||'{"reserved_note":"Reserva original QA","summary_visibility":"patient","summary_body":"Resumen compartido original QA","confirm_publish":true,"request_intervention":true,"request_body":"Solicitud mínima neutral QA"}'::jsonb);
select public.care_record_write('finalize',(select p from records_fixture where name='original'));
select pg_temp.care_assert((select status='final' and revision=1 and version=2 and first_finalized_at=now() from public.care_session_records),'Finalization persists original timestamp and revision');
select pg_temp.care_assert(public.care_record_read('b4000000-0000-4000-8000-000000000001')->'draft'='null'::jsonb,'Finalization removes private working draft');
select pg_temp.care_assert((select count(*)=1 from public.care_intervention_requests),'Explicit direction request persists once on finalization');
select public.care_record_write('finalize',(select p from records_fixture where name='original'));
select pg_temp.care_assert(jsonb_array_length(public.care_record_read('b4000000-0000-4000-8000-000000000001')->'versions')=1,'Finalization replay preserves unique original');
select pg_temp.care_denied($$select public.care_record_write('finalize',pg_temp.record_p(1,'psychology',2))$$,'Finalized record requires amendment','P0001');
select pg_temp.care_denied($$select public.care_record_write('amend',pg_temp.record_p(1,'psychology',2))$$,'Amendment requires reason','P0001');
select pg_temp.care_denied($$select public.care_record_write('draft',pg_temp.record_p(1,'psychology',2)||'{"id":"b4000000-0000-4000-8000-000000000009","version":0}'::jsonb)$$,'Same patient session professional type duplicate prevented','23505');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000006',true);
select pg_temp.care_assert(public.care_record_read('b4000000-0000-4000-8000-000000000001')->'versions'->0->'reserved_note'='null'::jsonb,'Direction reads finalized coordination without reserve');
select pg_temp.care_assert((select count(*)=1 from public.care_intervention_requests),'Direction receives minimal request separately from reserve');
select public.care_request_receive((select id from public.care_intervention_requests limit 1));
select public.care_request_receive((select id from public.care_intervention_requests limit 1));
select pg_temp.care_assert((select state='received' and received_by=auth.uid() from public.care_intervention_requests),'Direction reception idempotent and identified, not execution');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);
select pg_temp.care_denied($$select public.care_record_read('b4000000-0000-4000-8000-000000000001')$$,'Patient cannot read clinical private RPC');
select pg_temp.care_assert((select count(*)=0 from public.care_session_records),'Patient no clinical metadata grant through policy');
select pg_temp.care_assert((select count(*)=1 from public.care_record_summaries),'Patient explicitly published summary only');
select pg_temp.care_assert(public.care_record_shared('b2000000-0000-4000-8000-000000000001')->'summaries'->0->>'body'='Resumen compartido original QA','Own shared summary current source');
select pg_temp.care_assert((select count(*)=0 from public.care_intervention_requests),'Patient does not receive internal request');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000002',true);
select pg_temp.care_assert((select count(*)=0 from public.care_record_summaries),'B no A summary');
select pg_temp.care_denied($$select public.care_record_shared('b2000000-0000-4000-8000-000000000001')$$,'B no foreign summary resolver');
select pg_temp.care_denied($$select public.care_record_read('b4000000-0000-4000-8000-000000000001')$$,'B no clinical version');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000003',true);
select public.care_record_access_manage('b4000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000006',true);
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000006',true);
select pg_temp.care_assert(public.care_record_read('b4000000-0000-4000-8000-000000000001')->'versions'->0->>'reserved_note'='Reserva original QA','Explicit reader grant gives direction reserve');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000003',true);
select public.care_record_access_manage('b4000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000006',false);
select pg_temp.care_denied($$select public.care_record_access_manage('b4000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000007',true)$$,'CMS editor cannot be reader without clinical scope');
select public.care_record_write('draft',pg_temp.record_p(1,'psychology',2)||jsonb_build_object('payload',jsonb_build_object('objective','Objetivo QA','evolution','stable','facts','Enmienda privada QA')));
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000006',true);
select pg_temp.care_assert(public.care_record_read('b4000000-0000-4000-8000-000000000001')->'draft'='null'::jsonb,'Amendment draft remains private even after finalization');
select pg_temp.care_assert(public.care_record_read('b4000000-0000-4000-8000-000000000001')->'versions'->0->'reserved_note'='null'::jsonb,'Reader revocation hides prior reserve versions');
select pg_temp.care_denied($$select public.care_record_write('amend',pg_temp.record_p(1,'psychology',3)||'{"reason":"Ajena QA"}'::jsonb)$$,'Direction cannot amend professional record');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000003',true);
select public.care_record_write('amend',pg_temp.record_p(1,'psychology',3)||'{"reason":"Enmienda propia QA","summary_visibility":"coordination","summary_body":"Coordinación actual QA"}'::jsonb);
select pg_temp.care_assert(jsonb_array_length(public.care_record_read('b4000000-0000-4000-8000-000000000001')->'versions')=2,'Original and amendment clinical payload preserved');
select pg_temp.care_assert((select revision=2 and first_finalized_at=now() from public.care_session_records),'Amendment preserves original finalization');
select pg_temp.care_assert((select count(*)=1 from public.care_intervention_requests),'Amendment does not duplicate intervention request');
select pg_temp.care_assert(jsonb_array_length(public.care_record_events('b2000000-0000-4000-8000-000000000001'))=2,'Own patient sessions exclude cancellation and other event owners');
reset role;
insert into public.care_events(id,title,kind,starts_at,ends_at,professional_id,modality,created_by) select ('b6000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Actividad de otro paciente QA','individual',now()+interval '1 day',now()+interval '25 hours','b1000000-0000-4000-8000-000000000003','remote','b1000000-0000-4000-8000-000000000003' from generate_series(1,26)n;
insert into public.care_event_participants(event_id,patient_id) select id,'b2000000-0000-4000-8000-000000000002' from public.care_events where id::text like 'b6000000-%';
set local role authenticated;
select pg_temp.care_assert(jsonb_array_length(public.care_record_events('b2000000-0000-4000-8000-000000000001'))=2,'Patient source filter precedes limit despite 26 later unrelated sessions');
select pg_temp.care_denied($$select public.care_record_events('b2000000-0000-4000-8000-000000000002')$$,'Source resolver rejects foreign patient even if former event author');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);
select pg_temp.care_assert(public.care_record_shared('b2000000-0000-4000-8000-000000000001')->>'total'='0','Current unpublished amendment is absent from patient current summaries');
select pg_temp.care_assert((select count(*)=1 from public.care_record_summaries),'Previously explicit patient publication remains historical; coordination amendment never leaks');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000004',true);
select public.care_record_write('finalize',pg_temp.record_p(2,'recovery')||jsonb_build_object('author_id','b1000000-0000-4000-8000-000000000006','payload',jsonb_build_object('objective','Organización cualitativa QA','evolution','not_evaluable','autonomy','Descripción sin puntaje QA','activity_type','individual','recovery_participation','full','support','occasional','support_details','Apoyo observado QA','facts','Tarea y resultado neutral QA','progress','Sin avances observables QA','difficulties','Sin dificultades observables QA','evidence_source','observed','evidence','Observación directa neutral QA','no_commitment_reason','No se acordó nueva tarea QA')));
select pg_temp.care_assert(public.care_record_read('b4000000-0000-4000-8000-000000000002')->'versions'->0->'payload'->>'autonomy'='Descripción sin puntaje QA','Recovery qualitative observation finalizes without invented rubric');
select pg_temp.care_assert((select author_id=auth.uid() from public.care_session_records where id='b4000000-0000-4000-8000-000000000002'),'Forged author is ignored; authenticated professional is author');
select pg_temp.care_denied($$select public.care_record_write('finalize',pg_temp.record_p(3,'psychiatry'))$$,'Recovery cannot choose medical specialty');
select pg_temp.care_denied($$select public.care_record_write('amend',pg_temp.record_p(2,'recovery',1)||jsonb_build_object('reason','Inyección QA','payload',jsonb_build_object('objective','QA objetivo','evolution','stable','medical_changes','Forjada')))$$,'Recovery cannot inject medical indication','P0001');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000005',true);
select public.care_record_write('finalize',pg_temp.record_p(3,'psychiatry')||jsonb_build_object('payload',jsonb_build_object('objective','Control neutral QA','evolution','not_evaluable','adherence_reported','Referida neutral QA','adherence_observed','Sin evidencia observada QA','medical_indications','Texto sintético sin medicamento QA')));
select pg_temp.care_assert(public.care_record_read('b4000000-0000-4000-8000-000000000003')->'versions'->0->'payload'->>'adherence_observed'='Sin evidencia observada QA','Psychiatry separates referred and observed adherence, authorized manual indication');
reset role;update public.care_staff_capabilities set capabilities=array['care.patient.read','care.records.read','care.records.create'] where user_id='b1000000-0000-4000-8000-000000000005';
set local role authenticated;
select pg_temp.care_denied($$select public.care_record_write('amend',pg_temp.record_p(3,'psychiatry',1)||'{"reason":"Permiso retirado QA"}'::jsonb)$$,'Medical capability revocation prevents editing existing indications even by clearing fields');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000007',true);
select pg_temp.care_assert((select count(*)=0 from public.care_session_records),'CMS editor no clinical inheritance');
select pg_temp.care_denied($$select public.care_record_read('b4000000-0000-4000-8000-000000000001')$$,'CMS editor no record RPC');
select pg_temp.care_denied($$delete from public.care_record_summaries$$,'Direct summary deletion forbidden');
select pg_temp.care_denied($$update public.care_session_records set status='draft'$$,'Direct finalized overwrite forbidden');
select pg_temp.care_denied($$select * from private.care_record_versions$$,'Private clinical version table not exposed');
reset role;update public.care_assignments set ends_at=now() where professional_id='b1000000-0000-4000-8000-000000000003';
set local role authenticated;select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000003',true);
select pg_temp.care_denied($$select public.care_record_read('b4000000-0000-4000-8000-000000000001')$$,'Revocation denies authors own clinical history with prior JWT');
select pg_temp.care_denied($$select public.care_record_write('draft',pg_temp.record_p(1,'psychology',4))$$,'Revocation denies author draft writes');
reset role;update public.patient_profiles set is_active=false where id='b2000000-0000-4000-8000-000000000001';
set local role authenticated;select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);
select pg_temp.care_denied($$select public.care_record_shared('b2000000-0000-4000-8000-000000000001')$$,'Suspended patient cannot resolve previously shared summary');
select pg_temp.care_assert((select count(*)=0 from public.care_record_summaries),'Suspension hides explicit publication with prior JWT');
reset role;
select pg_temp.care_assert(exists(select 1 from private.care_audit where actor_id::text like 'b1000000-%' and action='care.record.read') and not exists(select 1 from private.care_audit a where actor_id::text like 'b1000000-%' and (to_jsonb(a)::text like '%Reserva original QA%' or to_jsonb(a)::text like '%Hechos neutros QA%')),'Actual sensitive reads audited without fixture clinical text');
rollback;
